export async function getListing(req, res, next) { try { const listing = await Listing.findById(req.params.id).populate('seller', 'name email'); if (!listing) return res.status(404).json({ message: 'Listing not found' }); const bids = await Bid.find({ listing: listing.id }).populate('bidder', 'name').sort({ amount: -1, createdAt: 1 }); res.json({ listing, bids }); } catch (error) { next(error); } }
export async function createListing(req, res, next) { try { const { title, category, description, condition, startingPrice, minimumIncrement, closesAt, photos = [] } = req.body; if (!title || !category || !description || !condition || !startingPrice || !minimumIncrement || !closesAt) return res.status(400).json({ message: 'All listing fields are required' }); const listing = await Listing.create({ seller: req.user.id, title, category, description, condition, photos, startingPrice, currentPrice: startingPrice, minimumIncrement, closesAt }); res.status(201).json({ listing }); } catch (error) { next(error); } }
export async function placeBid(req, res, next) { try { const amount = Number(req.body.amount); if (!Number.isFinite(amount) || amount <= 0) return res.status(400).json({ message: 'Bid amount must be a positive number' }); const listing = await Listing.findOneAndUpdate({ _id: req.params.id, status: 'ACTIVE', closesAt: { $gt: new Date() }, seller: { $ne: req.user.id }, $expr: { $or: [{ $and: [{ $eq: ['$currentPrice', '$startingPrice'] }, { $gte: [amount, '$startingPrice'] }] }, { $gte: [amount, { $add: ['$currentPrice', '$minimumIncrement'] }] }] } }, { $set: { currentPrice: amount } }, { new: true }); if (!listing) return res.status(409).json({ message: 'Bid is too low, auction is closed, or you cannot bid on your own listing' }); const bid = await Bid.create({ listing: listing.id, bidder: req.user.id, amount }); res.status(201).json({ bid, listing }); } catch (error) { next(error); } }

