import Listing from '../models/Listing.js';
import Bid from '../models/Bid.js';
import fs from 'node:fs/promises';
import path from 'node:path';
export async function listListings(req, res, next) { try { const query = { status: 'ACTIVE', ...(req.query.category ? { category: req.query.category } : {}) }; const listings = await Listing.find(query).populate('seller', 'name').sort({ closesAt: 1 }).limit(50); res.json({ listings }); } catch (error) { next(error); } }
export async function getListing(req, res, next) { try { const listing = await Listing.findById(req.params.id).populate('seller', 'name'); if (!listing) return res.status(404).json({ message: 'Listing not found' }); const bids = await Bid.find({ listing: listing.id }).select('amount createdAt').sort({ createdAt: -1 }).lean(); res.json({ listing, bids }); } catch (error) { next(error); } }
export async function createListing(req, res, next) { try { const { title, category, description, condition, startingPrice, minimumIncrement, closesAt } = req.body; if (!title || !category || !description || !condition || startingPrice === undefined || minimumIncrement === undefined || !closesAt) return res.status(400).json({ message: 'All listing fields are required' }); const photos = (req.files || []).map((file) => `/uploads/${file.filename}`); const listing = await Listing.create({ seller: req.user.id, title, category, description, condition, photos, startingPrice, currentPrice: startingPrice, minimumIncrement, hasBids: false, closesAt }); res.status(201).json({ listing }); } catch (error) { next(error); } }
export async function placeBid(req, res, next) { try { const amount = Number(req.body.amount); if (!Number.isFinite(amount) || amount <= 0) return res.status(400).json({ message: 'Bid amount must be a positive number' }); const listing = await Listing.findOneAndUpdate({ _id: req.params.id, status: 'ACTIVE', closesAt: { $gt: new Date() }, seller: { $ne: req.user.id }, $expr: { $or: [{ $and: [{ $eq: [{ $ifNull: ['$hasBids', false] }, false] }, { $gte: [amount, '$startingPrice'] }] }, { $gte: [amount, { $add: ['$currentPrice', '$minimumIncrement'] }] }] } }, { $set: { currentPrice: amount, hasBids: true } }, { new: true }); if (!listing) return res.status(409).json({ message: 'Bid is too low, the auction is closed, or you cannot bid on your own listing' }); const bid = await Bid.create({ listing: listing.id, bidder: req.user.id, amount }); res.status(201).json({ bid: { amount: bid.amount, createdAt: bid.createdAt }, listing }); } catch (error) { next(error); } }
export async function deleteListing(req, res, next) { try { const listing = await Listing.findOne({ _id: req.params.id, seller: req.user.id }); if (!listing) return res.status(404).json({ message: 'Listing not found or you are not the seller' }); const bidCount = await Bid.countDocuments({ listing: listing.id }); if (bidCount > 0) return res.status(409).json({ message: 'An auction with bids cannot be deleted' }); await Listing.deleteOne({ _id: listing.id }); await Promise.all(listing.photos.filter((photo) => photo.startsWith('/uploads/')).map((photo) => fs.unlink(path.resolve(photo.slice(1))).catch(() => undefined))); res.json({ message: 'Listing deleted successfully' }); } catch (error) { next(error); } }

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import NavBar from '../components/NavBar';
import api from '../services/api';

const initialForm = {
  title: '',
  category: '',
  description: '',
  condition: '',
  startingPrice: '',
  minimumIncrement: '',
  closesAt: '',
  photos: []
};

export default function CreateListingPage() {
  const navigate = useNavigate();
  const [form, setForm] = useState(initialForm);
  const [state, setState] = useState({ loading: false, error: '' });

  function updateField(event) {
    setForm((current) => ({ ...current, [event.target.name]: event.target.value }));
  }

  function updatePhotos(event) {
    setForm((current) => ({ ...current, photos: Array.from(event.target.files || []) }));
  }

  async function submit(event) {
    event.preventDefault();
    setState({ loading: true, error: '' });
    try {
      const payload = new FormData();
      Object.entries(form).forEach(([key, value]) => {
        if (key !== 'photos') payload.append(key, value);
      });
      form.photos.forEach((photo) => payload.append('photos', photo));
      await api.post('/listings', payload);
      navigate('/marketplace');
    } catch (error) {
      setState({ loading: false, error: error.response?.data?.message || 'Unable to create the listing.' });
    }
  }

  return <><NavBar /><main className="auth-card listing-form">
    <p className="eyebrow">Sell on campus</p><h1>Create listing</h1>
    <form onSubmit={submit}>
      <label>Title<input name="title" value={form.title} onChange={updateField} maxLength="120" required /></label>
      <label>Category<input name="category" value={form.category} onChange={updateField} placeholder="Books, electronics, furniture..." required /></label>
      <label>Description<textarea name="description" value={form.description} onChange={updateField} maxLength="3000" rows="4" required /></label>
      <label>Condition<input name="condition" value={form.condition} onChange={updateField} placeholder="Good, like new..." required /></label>
      <label>Starting price<input name="startingPrice" type="number" min="0" step="0.01" value={form.startingPrice} onChange={updateField} required /></label>
      <label>Minimum bid increment<input name="minimumIncrement" type="number" min="1" step="0.01" value={form.minimumIncrement} onChange={updateField} required /></label>
      <label>Closing date and time<input name="closesAt" type="datetime-local" value={form.closesAt} onChange={updateField} required /></label>
      <label>Photos <span className="muted">(up to 5 images, 5 MB each)</span><input name="photos" type="file" accept="image/*" multiple onChange={updatePhotos} /></label>
      {state.error && <p className="form-error" role="alert">{state.error}</p>}
      <button className="button" type="submit" disabled={state.loading}>{state.loading ? 'Creating listing...' : 'Create listing'}</button>
    </form>
  </main></>;
}

