import fs from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import multer from 'multer';

const uploadDirectory = fileURLToPath(new URL('../../uploads', import.meta.url));
fs.mkdirSync(uploadDirectory, { recursive: true });

const storage = multer.diskStorage({
  destination: uploadDirectory,
  filename: (req, file, callback) => {
    const extension = path.extname(file.originalname).toLowerCase();
    callback(null, `${Date.now()}-${randomUUID()}${extension}`);
  }
});

const imageOnly = (req, file, callback) => {
  if (file.mimetype.startsWith('image/')) return callback(null, true);
  const error = new Error('Only image files are allowed');
  error.statusCode = 400;
  callback(error);
};

export const listingImages = multer({
  storage,
  fileFilter: imageOnly,
  limits: { files: 5, fileSize: 5 * 1024 * 1024 }
}).array('photos', 5);

import axios from 'axios';

const api = axios.create({
  baseURL: import.meta.env.VITE_API_URL || 'http://localhost:5001/api'
});

api.interceptors.request.use((config) => {
  const token = localStorage.getItem('campusbid_token');
  if (token) config.headers.Authorization = `******;
  return config;
});

export async function getHealth() {
  const { data } = await api.get('/health');
  return data;
}

export async function getListings(params = {}) {
  const { data } = await api.get('/listings', { params });
  return data;
}

export async function getListing(id) {
  const { data } = await api.get(`/listings/${id}`);
  return data;
}

export async function placeBid(id, amount) {
  const { data } = await api.post(`/listings/${id}/bids`, { amount });
  return data;
}

export async function deleteListing(id) {
  const { data } = await api.delete(`/listings/${id}`);
  return data;
}

export function getMediaUrl(mediaPath) {
  if (!mediaPath || mediaPath.startsWith('http')) return mediaPath;
  const apiUrl = import.meta.env.VITE_API_URL || 'http://localhost:5000/api';
  return `${apiUrl.replace(/\/api\/?$/, '')}${mediaPath}`;
}

export default api;

